START TRANSACTION;
SELECT * FROM transfer_requests WHERE id = 8001 FOR UPDATE;
-- Both transfer directions lock account IDs in ascending order.
SELECT * FROM accounts WHERE id = 101 FOR UPDATE;
SELECT * FROM accounts WHERE id = 202 FOR UPDATE;
-- Handler checks persisted request, currency, positive amount and account status.
UPDATE accounts SET balance = balance - 5000.00 WHERE id = 101 AND balance >= 5000.00;
-- If ROW_COUNT() != 1: do not credit; roll back/record confirmed business rejection.
UPDATE accounts SET balance = balance + 5000.00 WHERE id = 202;
INSERT INTO account_transactions (id,account_id,transfer_id,type,amount,reference_no,status) VALUES
(9101,101,8001,'DEBIT',5000.00,'TR-8001-D','SUCCESS'),
(9102,202,8001,'CREDIT',5000.00,'TR-8001-C','SUCCESS');
UPDATE transfer_requests SET status = 'SUCCESS' WHERE id = 8001;
